/**
 * browser/parity-boot.js — the RUNTIME half of the BROWSER condition target of
 * `@descix/frqtl-sdk`'s `.` specifier.
 *
 * `.` is THE PARITY CORE: one specifier, two condition targets, ONE symbol contract.
 * The node condition is `dist/node/index.js` (+ its generated `.mjs` face); the browser
 * condition is `dist/browser/index.js`, which is GENERATED by build.js and calls exactly
 * one function — this one. CEO R1: *"Anything in the npm should be equally accessible via
 * the browser or node."*
 *
 * ── Why the browser target is generated and this file is not ────────────────
 *
 * ES named exports are static, so the browser barrel must SPELL its export names in
 * source. Spelling them by hand would be a second derivation of the symbol contract the
 * roster (`lib/frqtl/objects/public-parts.js::PUBLIC_PARTS`) owns — the exact mirror drift
 * whose tell is "a part that imports in node and is `undefined` in a page". So build.js
 * GENERATES that name list from the strongest source available (the BUILT node barrel's
 * own `Object.keys()`, the same source the `.mjs` wrapper is generated from), and this
 * file — which contains NO list — provides the mechanism the generated module drives.
 *
 * ── Mechanism: the canonical classic-script stack, not a second engine ──────
 *
 * The shipped engine / renderer / game layer are classic dual-mode scripts (the canonical
 * discipline — see `lib/shim/engine/game-layer-manifest.js`). This module injects that
 * SAME stack, in the SAME canonical order, resolved through `engineRouter` — the ONE path
 * authority — and takes its script lists from `buildScriptLists` (`../esm/index.js`),
 * which reads the two manifest owners. It adds ZERO physics and re-implements nothing:
 * after injection it FERRIES `window[name]` for each name the generated module passes.
 *
 * The lists are handed in by the generated module rather than computed here because the
 * two extra-script facts (a roster row absent from `GAME_LAYER_SCRIPTS`; a fixed barrel
 * member absent from both manifests) are DERIVED AT BUILD TIME off those same owners —
 * see build.js step 8g. Editing the manifests themselves is their own authority and is
 * parity-tested against `experiments/_shared/stack-boot.js`.
 *
 * FAIL LOUD: a name that resolves `undefined` after the stack has loaded throws, naming
 * every missing symbol and the roster that owns the contract — never a silently missing
 * export, which for a parity core is worse than a refused door because it fails at the
 * SYMBOL instead of at the DOOR.
 */

import { engineRouter } from '../ide/engine/router.js';
// The lists AND the one classic-script sequencer (injectScriptList → lib/shim/engine/
// script-sequencer.js): this module carries no injector of its own.
import { buildScriptLists, injectScriptList } from '../esm/index.js';

var _boot = null;

/**
 * Boot the canonical stack and return the parity-core symbol bag.
 *
 * @param {{base: string, names: string[], extraScripts: string[]}} spec
 *   base         — the package's `dist/` URL (the generated module derives it from its own
 *                  `import.meta.url`, so a CDN copy and a self-hosted copy both work with
 *                  no configuration).
 *   names        — the symbol contract, generated off the built node barrel.
 *   extraScripts — router-relative paths NOT covered by the manifest-derived lists,
 *                  derived at build time off the roster + the two manifests.
 * @returns {Promise<Object>} frozen bag of `name → window[name]`
 */
export function bootParityCore(spec) {
    if (_boot) { return _boot; }

    if (typeof document === 'undefined') {
        throw new Error(
            '[frqtl-sdk] the BROWSER condition of `@descix/frqtl-sdk` was loaded in a host with no\n' +
            'DOM. The parity core boots by injecting the canonical classic <script> stack, which\n' +
            'needs a document.\n' +
            '\n' +
            'THE RIGHT DOOR HERE is the SAME specifier under node — `require(\'@descix/frqtl-sdk\')`\n' +
            'or `import { ... } from \'@descix/frqtl-sdk\'` — which Node resolves to the node\n' +
            'condition target automatically. Reaching this file means the "node" condition was\n' +
            'bypassed (a bundler configured for the browser, or a deep dist/ path).\n' +
            '\n' +
            '(FAIL-LOUD. Both conditions export the SAME symbols; this is a resolution problem,\n' +
            'not a missing feature.)'
        );
    }

    _boot = (async function () {
        // Trailing slash stripped: engineRouter joins base + '/' + path, so a base ending in
        // '/' (which `new URL('..', import.meta.url)` always does) would yield a doubled slash.
        var base = String(spec.base).replace(/\/+$/, '');
        var router = engineRouter({ mode: 'cdn', engine: 'wasm', base: base });
        var lists = buildScriptLists(router);
        var extras = spec.extraScripts.map(function (p) { return { src: router.resolve(p) }; });
        // The page's path authority (window._egptEnginePathMap + its function form, the
        // in-page door window._egptResolveFrqtl) is published by the router itself — the one
        // ESM-side publisher; a different router already on the page THROWS.
        router.ensureBrowserPathMap();

        await injectScriptList(router, lists.ENGINE);
        await injectScriptList(router, lists.RENDERER);
        await injectScriptList(router, lists.GAME.concat(extras));

        var api = {};
        var missing = [];
        for (var i = 0; i < spec.names.length; i++) {
            var n = spec.names[i];
            var v = globalThis[n];
            if (v === undefined) { missing.push(n); } else { api[n] = v; }
        }
        if (missing.length > 0) {
            throw new Error(
                '[frqtl-sdk] parity core: the canonical stack loaded but ' + missing.length +
                ' published symbol(s) are undefined on the page: ' + missing.join(', ') + '.\n' +
                'The symbol contract is owned by lib/frqtl/objects/public-parts.js::PUBLIC_PARTS\n' +
                '(plus the fixed barrel members); a name here that never reaches `window` means the\n' +
                'script publishing it was not injected — fix the build-time derivation in\n' +
                'sdk/frqtl-sdk/build.js step 8g, never by hand-listing it in a barrel.\n' +
                '(FAIL-LOUD: a published barrel never ships a silently missing export.)'
            );
        }
        return Object.freeze(api);
    })();

    return _boot;
}
